//! Independently decode a bounded direct Memo -> USDC transfer() observation.
//! Raw RPC assertions are evidence inputs, not authenticated consensus proofs.
use crate::reconciliation::{self, Bundle, Decision, Transfer, Trust};
use arkhe_core::{canonical::encode_value, Digest32};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use sha3::{Digest, Keccak256};

const MEMO: &str = "0x5294e9927c3306dcbadb03fe70b92e01ccede505";
const SYSTEM: &str = "0xfffffffffffffffffffffffffffffffffffffffe";
const USDC: &str = "0x3600000000000000000000000000000000000000";
const TRANSFER_TOPIC: &str = "0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef";
const MEMO_TOPIC: &str = "0xeb15ee720798341c37739df41be53acfbbf70ae6802dade35457beec6e47a5e4";
const BEFORE_TOPIC: &str = "0xb252e055da754c72fbf7542cf424b190808a9b541e912894c5e15b4238c41501";
const SCALE: u128 = 1_000_000_000_000;

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct MemoEvidence {
    pub profile: String,
    pub chain_response: Vec<u8>,
    pub receipt_response: Vec<u8>,
    pub block_response: Vec<u8>,
    pub finalized_response: Vec<u8>,
}

impl MemoEvidence {
    fn bounded(&self) -> Result<(), &'static str> {
        if self.profile != "arkhe/arc-direct-memo-evidence/v1"
            || [
                &self.chain_response,
                &self.receipt_response,
                &self.block_response,
                &self.finalized_response,
            ]
            .iter()
            .any(|v| v.is_empty() || v.len() > 1_000_000)
        {
            return Err("invalid or oversized memo evidence");
        }
        Ok(())
    }
    pub fn commitment(&self) -> Result<Digest32, &'static str> {
        self.bounded()?;
        Ok(Digest32::blake3(
            b"AKG:ARC:DIRECT-MEMO-EVIDENCE:v1\0",
            &encode_value(&serde_json::to_value(self).map_err(|_| "memo encoding failed")?),
        ))
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct MemoBundle {
    pub reconciliation: Bundle,
    pub evidence: MemoEvidence,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MemoObservation {
    pub transfer: Transfer,
    pub memo_id: String,
    pub memo_hex: String,
    pub call_data_hash: String,
    pub finalized_head_number: u64,
}

fn result(raw: &[u8]) -> Result<Value, &'static str> {
    let v: Value = serde_json::from_slice(raw).map_err(|_| "invalid RPC JSON")?;
    if v["jsonrpc"] != "2.0"
        || v["id"].as_u64().is_none()
        || v.get("error").is_some()
        || v.get("result").is_none_or(Value::is_null)
    {
        return Err("invalid RPC envelope");
    }
    Ok(v["result"].clone())
}
fn text(v: &Value) -> Result<&str, &'static str> {
    v.as_str().ok_or("missing string field")
}
fn hex_bytes(v: &Value, size: usize) -> Result<Vec<u8>, &'static str> {
    let s = text(v)?;
    if !s.starts_with("0x") || s.len() != 2 + size * 2 {
        return Err("invalid hex width");
    }
    hex::decode(&s[2..]).map_err(|_| "invalid hex bytes")
}
fn normalized(v: &Value, size: usize) -> Result<String, &'static str> {
    Ok(format!("0x{}", hex::encode(hex_bytes(v, size)?)))
}
fn quantity(v: &Value) -> Result<u64, &'static str> {
    let s = text(v)?.strip_prefix("0x").ok_or("invalid hex quantity")?;
    if s.is_empty() || s.len() > 16 || !s.bytes().all(|c| c.is_ascii_hexdigit()) {
        return Err("invalid or excessive hex quantity");
    }
    u64::from_str_radix(s, 16).map_err(|_| "quantity overflow")
}
fn small_word(word: &[u8]) -> Result<u128, &'static str> {
    if word.len() != 32 || word[..16].iter().any(|b| *b != 0) {
        return Err("ABI integer too large");
    }
    Ok(u128::from_be_bytes(
        word[16..].try_into().map_err(|_| "invalid ABI word")?,
    ))
}
fn topic_address(v: &Value) -> Result<String, &'static str> {
    let bytes = hex_bytes(v, 32)?;
    if bytes[..12].iter().any(|b| *b != 0) {
        return Err("invalid indexed address padding");
    }
    Ok(format!("0x{}", hex::encode(&bytes[12..])))
}
fn log_index(log: &Value) -> Result<u64, &'static str> {
    quantity(&log["logIndex"])
}

/// Supported subset: one direct Memo frame, one native transfer and its ERC-20
/// mirror. Multiple/nested calls fail closed rather than guessing correlation.
pub fn observe(e: &MemoEvidence) -> Result<MemoObservation, &'static str> {
    e.bounded()?;
    if quantity(&result(&e.chain_response)?)? != 5042002 {
        return Err("wrong memo network");
    }
    let receipt = result(&e.receipt_response)?;
    let block = result(&e.block_response)?;
    let finalized = result(&e.finalized_response)?;
    let tx = normalized(&receipt["transactionHash"], 32)?;
    let block_hash = normalized(&receipt["blockHash"], 32)?;
    let block_number = quantity(&receipt["blockNumber"])?;
    let transaction_index = quantity(&receipt["transactionIndex"])?;
    let finalized_number = quantity(&finalized["number"])?;
    normalized(&finalized["hash"], 32)?;
    if quantity(&receipt["status"])? != 1
        || normalized(&receipt["to"], 20)? != MEMO
        || normalized(&block["hash"], 32)? != block_hash
        || quantity(&block["number"])? != block_number
        || block_number > finalized_number
    {
        return Err("receipt/block/finality inconsistency");
    }
    let transactions = block["transactions"]
        .as_array()
        .ok_or("missing block transactions")?;
    let position = usize::try_from(transaction_index).map_err(|_| "transaction index overflow")?;
    if transactions
        .get(position)
        .and_then(Value::as_str)
        .map(str::to_lowercase)
        .as_deref()
        != Some(tx.as_str())
        || (block_number == finalized_number && normalized(&finalized["hash"], 32)? != block_hash)
    {
        return Err("receipt transaction absent from supplied block");
    }
    let logs = receipt["logs"].as_array().ok_or("missing receipt logs")?;
    if logs.len() > 2048 {
        return Err("too many receipt logs");
    }
    let mut before = Vec::new();
    let mut memos = Vec::new();
    let mut movements = Vec::new();
    let mut mirrors = Vec::new();
    let mut indices = std::collections::BTreeSet::new();
    for log in logs {
        let address = normalized(&log["address"], 20)?;
        if !matches!(address.as_str(), MEMO | SYSTEM | USDC) {
            continue;
        }
        if log["removed"] != false
            || normalized(&log["blockHash"], 32)? != block_hash
            || normalized(&log["transactionHash"], 32)? != tx
            || quantity(&log["blockNumber"])? != block_number
            || quantity(&log["transactionIndex"])? != transaction_index
            || !indices.insert(log_index(log)?)
        {
            return Err("log provenance or index mismatch");
        }
        let topics = log["topics"].as_array().ok_or("missing event topics")?;
        let topic = normalized(topics.first().ok_or("empty topics")?, 32)?;
        match (address.as_str(), topic.as_str()) {
            (MEMO, BEFORE_TOPIC) => before.push(log),
            (MEMO, MEMO_TOPIC) => memos.push(log),
            (SYSTEM, TRANSFER_TOPIC) => movements.push(log),
            (USDC, TRANSFER_TOPIC) => mirrors.push(log),
            _ => {}
        }
    }
    if before.len() != 1 || memos.len() != 1 || movements.len() != 1 || mirrors.len() != 1 {
        return Err("unsupported or ambiguous memo frame");
    }
    let (b, m, t, mirror) = (before[0], memos[0], movements[0], mirrors[0]);
    if b["topics"].as_array().map(Vec::len) != Some(2)
        || text(&b["data"])? != "0x"
        || m["topics"].as_array().map(Vec::len) != Some(4)
        || t["topics"].as_array().map(Vec::len) != Some(3)
        || mirror["topics"].as_array().map(Vec::len) != Some(3)
        || !(log_index(b)? < log_index(t)?
            && log_index(t)? < log_index(mirror)?
            && log_index(mirror)? < log_index(m)?)
    {
        return Err("invalid memo frame ordering or shape");
    }
    let data_str = text(&m["data"])?;
    if !data_str.starts_with("0x") || data_str.len() > 2 + 2 * (128 + 4096) {
        return Err("invalid memo data size");
    }
    let data = hex::decode(&data_str[2..]).map_err(|_| "invalid memo ABI hex")?;
    if data.len() < 128 || small_word(&data[32..64])? != 96 {
        return Err("invalid memo ABI offset");
    }
    let len = usize::try_from(small_word(&data[96..128])?).map_err(|_| "memo length overflow")?;
    if len > 4096
        || data.len() != 128 + len.div_ceil(32) * 32
        || data[128 + len..].iter().any(|b| *b != 0)
        || hex_bytes(&b["topics"][1], 32)? != data[64..96]
    {
        return Err("invalid memo length/padding/frame index");
    }
    let payer = topic_address(&t["topics"][1])?;
    let payee = topic_address(&t["topics"][2])?;
    if normalized(&receipt["from"], 20)? != payer
        || topic_address(&m["topics"][1])? != payer
        || topic_address(&m["topics"][2])? != USDC
        || topic_address(&mirror["topics"][1])? != payer
        || topic_address(&mirror["topics"][2])? != payee
        || payer == format!("0x{}", "00".repeat(20))
        || payee == format!("0x{}", "00".repeat(20))
    {
        return Err("memo sender/target/transfer parties mismatch");
    }
    let native = small_word(&hex_bytes(&t["data"], 32)?)?;
    let amount = u64::try_from(native / SCALE).map_err(|_| "amount overflow")?;
    if native % SCALE != 0
        || amount == 0
        || small_word(&hex_bytes(&mirror["data"], 32)?)? != u128::from(amount)
    {
        return Err("native/ERC20 amount or precision mismatch");
    }
    let mut calldata = vec![0xa9, 0x05, 0x9c, 0xbb];
    calldata.extend(hex_bytes(&t["topics"][2], 32)?);
    calldata.extend([0u8; 24]);
    calldata.extend(amount.to_be_bytes());
    let hash: [u8; 32] = Keccak256::digest(&calldata).into();
    if data[..32] != hash {
        return Err("memo calldata hash mismatch");
    }
    let memo_id = normalized(&m["topics"][3], 32)?;
    if hex_bytes(&m["topics"][3], 32)?.iter().all(|b| *b == 0) {
        return Err("zero memo ID is not a reference");
    }
    Ok(MemoObservation {
        transfer: Transfer {
            chain_id: 5042002,
            block_number,
            block_hash,
            transaction_hash: tx,
            event_index: u32::try_from(log_index(t)?).map_err(|_| "log index overflow")?,
            from: payer,
            to: payee,
            amount_microusd: amount,
            observed_at: quantity(&block["timestamp"])?,
            reference: format!("arc-memo-id:{memo_id}"),
            source: format!("arc-memo-evidence:blake3:{}", e.commitment()?.to_hex()),
            synthetic: false,
        },
        memo_id,
        memo_hex: format!("0x{}", hex::encode(&data[128..128 + len])),
        call_data_hash: format!("0x{}", hex::encode(hash)),
        finalized_head_number: finalized_number,
    })
}

pub fn verify(bundle: &MemoBundle, trust: &Trust) -> Result<Decision, &'static str> {
    let observation = observe(&bundle.evidence)?;
    if bundle.reconciliation.record.input.transfer != observation.transfer {
        return Err("memo evidence does not derive the exact reconciliation transfer");
    }
    reconciliation::verify(&bundle.reconciliation, trust)
}

use crate::{error::VerifyError, hash::blake3_256, mmr::profile::mmr_size};
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ProofStep {
    pub kind: String,
    pub direction: String,
    pub hash: [u8; 32],
}

fn leaf_hash(x: &[u8]) -> [u8; 32] {
    let mut b = Vec::with_capacity(1 + x.len());
    b.push(0x00);
    b.extend_from_slice(x);
    blake3_256(&b)
}

fn node_hash(l: &[u8; 32], r: &[u8; 32]) -> [u8; 32] {
    let mut b = Vec::with_capacity(65);
    b.push(0x01);
    b.extend_from_slice(l);
    b.extend_from_slice(r);
    blake3_256(&b)
}

fn bag_hash(l: &[u8; 32], r: &[u8; 32], n: usize) -> [u8; 32] {
    let mut b = Vec::with_capacity(73);
    b.push(0x02);
    b.extend_from_slice(&mmr_size(n as u64).to_be_bytes());
    b.extend_from_slice(l);
    b.extend_from_slice(r);
    blake3_256(&b)
}

fn peak_widths(n: usize) -> Vec<usize> {
    let mut out = Vec::new();
    let mut bit = 1usize << (usize::BITS - 1 - n.leading_zeros());
    let mut rem = n;
    while bit > 0 {
        if rem >= bit {
            out.push(bit);
            rem -= bit;
        }
        bit >>= 1;
    }
    out
}

fn perfect_root_and_path(hashes: &[[u8; 32]], mut idx: usize) -> ([u8; 32], Vec<ProofStep>) {
    let mut level = hashes.to_vec();
    let mut steps = Vec::new();
    while level.len() > 1 {
        let sib = idx ^ 1;
        let direction = if sib < idx { "left" } else { "right" };
        steps.push(ProofStep {
            kind: "node".into(),
            direction: direction.into(),
            hash: level[sib],
        });
        level = level
            .chunks_exact(2)
            .map(|p| node_hash(&p[0], &p[1]))
            .collect();
        idx /= 2;
    }
    (level[0], steps)
}

pub fn build_root_and_proof(
    leaves: &[Vec<u8>],
    target: usize,
) -> Result<([u8; 32], Vec<ProofStep>), VerifyError> {
    if leaves.is_empty() {
        return Err(VerifyError::InvalidInput("empty MMR".into()));
    }
    if target >= leaves.len() {
        return Err(VerifyError::InvalidInput("target out of range".into()));
    }

    let hashes: Vec<[u8; 32]> = leaves.iter().map(|x| leaf_hash(x)).collect();
    let mut peaks = Vec::<(usize, usize, [u8; 32])>::new();
    let mut start = 0;
    for w in peak_widths(leaves.len()) {
        let (r, _) = perfect_root_and_path(&hashes[start..start + w], 0);
        peaks.push((start, w, r));
        start += w;
    }

    let mut root = peaks.last().unwrap().2;
    for p in peaks[..peaks.len() - 1].iter().rev() {
        root = bag_hash(&p.2, &root, leaves.len());
    }

    let (peak_i, start, width) = peaks
        .iter()
        .enumerate()
        .find_map(|(i, (s, w, _))| {
            if *s <= target && target < *s + *w {
                Some((i, *s, *w))
            } else {
                None
            }
        })
        .unwrap();

    let (_, mut proof) = perfect_root_and_path(&hashes[start..start + width], target - start);

    if peak_i < peaks.len() - 1 {
        let mut acc = peaks.last().unwrap().2;
        for p in peaks[peak_i + 1..peaks.len() - 1].iter().rev() {
            acc = bag_hash(&p.2, &acc, leaves.len());
        }
        proof.push(ProofStep {
            kind: "bag".into(),
            direction: "right".into(),
            hash: acc,
        });
    }

    for p in peaks[..peak_i].iter().rev() {
        proof.push(ProofStep {
            kind: "bag".into(),
            direction: "left".into(),
            hash: p.2,
        });
    }

    Ok((root, proof))
}

pub fn verify_proof(
    leaf: &[u8],
    leaf_count: usize,
    proof: &[ProofStep],
    expected_root: &[u8; 32],
) -> Result<bool, VerifyError> {
    if leaf_count == 0 {
        return Err(VerifyError::InvalidInput("empty MMR".into()));
    }
    // Bound untrusted counts before size arithmetic, including on wasm32.
    if (leaf_count as u64) > u64::MAX / 2 {
        return Err(VerifyError::InvalidInput("MMR size overflow".into()));
    }
    if !valid_shape(leaf_count, proof, None) {
        return Err(VerifyError::InvalidInput("invalid MMR proof shape".into()));
    }
    let mut cur = leaf_hash(leaf);
    for step in proof {
        cur = match (step.kind.as_str(), step.direction.as_str()) {
            ("node", "left") => node_hash(&step.hash, &cur),
            ("node", "right") => node_hash(&cur, &step.hash),
            ("bag", "left") => bag_hash(&step.hash, &cur, leaf_count),
            ("bag", "right") => bag_hash(&cur, &step.hash, leaf_count),
            _ => return Err(VerifyError::InvalidInput("invalid proof step".into())),
        };
    }
    Ok(&cur == expected_root)
}

/// Verify both membership and the claimed leaf position under the frozen profile.
pub fn verify_proof_at(
    leaf: &[u8],
    leaf_count: usize,
    leaf_index: usize,
    proof: &[ProofStep],
    expected_root: &[u8; 32],
) -> Result<bool, VerifyError> {
    if leaf_index >= leaf_count || !valid_shape(leaf_count, proof, Some(leaf_index)) {
        return Err(VerifyError::InvalidInput(
            "invalid MMR leaf position".into(),
        ));
    }
    verify_proof(leaf, leaf_count, proof, expected_root)
}

fn valid_shape(n: usize, proof: &[ProofStep], index: Option<usize>) -> bool {
    if n == 0 || proof.len() > 2 * usize::BITS as usize {
        return false;
    }
    let widths = peak_widths(n);
    let node_count = proof.iter().take_while(|step| step.kind == "node").count();
    let mut start = 0;
    for (peak, &width) in widths.iter().enumerate() {
        let depth = width.trailing_zeros() as usize;
        let right = usize::from(peak + 1 < widths.len());
        if depth == node_count
            && proof.len() == depth + right + peak
            && index.is_none_or(|i| i >= start && i - start < width)
        {
            let offset = index.map(|i| i - start);
            let nodes_ok = proof[..depth].iter().enumerate().all(|(level, step)| {
                step.kind == "node"
                    && match offset {
                        Some(i) => {
                            step.direction
                                == if (i >> level) & 1 == 1 {
                                    "left"
                                } else {
                                    "right"
                                }
                        }
                        None => matches!(step.direction.as_str(), "left" | "right"),
                    }
            });
            let bags_ok = proof[depth..].iter().enumerate().all(|(i, step)| {
                step.kind == "bag"
                    && step.direction
                        == if right == 1 && i == 0 {
                            "right"
                        } else {
                            "left"
                        }
            });
            if nodes_ok && bags_ok {
                return true;
            }
        }
        start += width;
    }
    false
}

pub mod inclusion;
pub mod profile;

pub use inclusion::{build_root_and_proof, verify_proof, verify_proof_at, ProofStep};

pub const PROFILE_ID: &str = "arkhe-mmr";
pub const PROFILE_VERSION: u16 = 1;
pub const PROFILE_DIGEST_HEX: &str =
    "bcd07a275061ef385fccdd184030c2358fdd0937477cb0ef30cf8148342f2450";

pub fn mmr_size(leaf_count: u64) -> u64 {
    2 * leaf_count - leaf_count.count_ones() as u64
}

//! Independent finite arithmetic proof checker. Never invokes the producer.
use arkhe_core::{
    output_proof::{BudgetProof, BudgetSpec, BUDGET_CHECKER, MAX_BUDGET_ITEMS},
    work::WorkIntent,
    worker::WorkerExecutionRecord,
    Digest32,
};

/// Trusted spec and policy come from governance, never from the certificate.
pub fn verify_budget_proof(
    proof: &BudgetProof,
    spec: &BudgetSpec,
    policy_digest: Digest32,
    intent: &WorkIntent,
    worker: &WorkerExecutionRecord,
) -> Result<Digest32, &'static str> {
    let n = proof.input.costs.len();
    if spec.version != 1
        || spec.max_items == 0
        || usize::from(spec.max_items) > MAX_BUDGET_ITEMS
        || n == 0
        || n > usize::from(spec.max_items)
        || proof.prefix_totals.len() != n + 1
        || proof.checker != BUDGET_CHECKER
        || policy_digest == Digest32::ZERO
        || proof.spec_digest != spec.digest()
        || proof.policy_digest != policy_digest
        || proof.intent_digest != intent.digest()
        || proof.worker_digest != worker.digest()
        || proof.input.digest() != worker.input_digest
        || proof.output.digest() != worker.output_digest
        || proof.output.digest() != intent.parameters_digest
    {
        return Err("budget proof profile, size or binding mismatch");
    }
    if proof.prefix_totals[0] != 0 {
        return Err("budget proof invalid base case");
    }
    // Use wider arithmetic, independently of the producer's checked u64 sum.
    for (cost, step) in proof.input.costs.iter().zip(proof.prefix_totals.windows(2)) {
        if u128::from(step[0]) + u128::from(*cost) != u128::from(step[1]) {
            return Err("budget proof invalid arithmetic step");
        }
    }
    if proof.prefix_totals[n] != proof.output.total || proof.output.total > spec.limit {
        return Err("budget proof conclusion rejected");
    }
    Ok(proof.digest())
}

//! AP2 v0.2 Payment Mandate leg: consumes authenticated results of a role's
//! verifier. It never interprets raw SD-JWT as an authenticated mandate.
use crate::{
    hash::sha256,
    mmr::{profile::PROFILE_DIGEST_HEX, verify_proof_at, ProofStep},
};
use arkhe_core::{formal_proof::*, work::WorkIntent, worker::WorkerExecutionRecord, Digest32};
use ed25519_dalek::{Signature, VerifyingKey};

pub const BRIDGE: &str = "arkhe-ap2-payment-role@1";
pub fn closed_digest(token: &str) -> Digest32 {
    Digest32::blake3(b"AKG:AP2:CLOSED:v1\0", token.as_bytes())
}
fn signature(key: &[u8; 32], digest: Digest32, sig: &[u8]) -> Result<(), &'static str> {
    let key = VerifyingKey::from_bytes(key).map_err(|_| "invalid AP2 bridge trust key")?;
    let sig = Signature::from_slice(sig).map_err(|_| "invalid AP2 bridge signature")?;
    key.verify_strict(&digest.0, &sig)
        .map_err(|_| "AP2 role/checkpoint signature rejected")
}
pub fn verify(
    proof: &PaymentProof,
    spec: &PaymentPolicy,
    policy: Digest32,
    intent: &WorkIntent,
    worker: &WorkerExecutionRecord,
) -> Result<(), &'static str> {
    let r = &proof.role;
    let c = &spec.retained_checkpoint;
    if proof.steps.len() > 64
        || proof.closed_sd_jwt.is_empty()
        || proof.closed_sd_jwt.len() > 65536
        || proof.checkout_jwt.is_empty()
        || proof.checkout_jwt.len() > 65536
        || proof
            .open_sd_jwt
            .as_ref()
            .is_some_and(|v| v.is_empty() || v.len() > 65536)
        || spec.version != 1
        || spec.role_id.is_empty()
        || r.bridge_profile != BRIDGE
        || r.ap2_version != "0.2"
        || r.role_id != spec.role_id
        || r.principal != intent.requested_by
        || r.operation_id != intent.operation_id()
        || policy == Digest32::ZERO
        || r.policy_digest != policy
        || !r.signatures_validated
        || !r.constraints_validated
        || !r.checkout_binding_validated
        || r.closed_mandate_id == Digest32::ZERO
        || r.closed_sha256 != sha256(proof.closed_sd_jwt.as_bytes())
        || r.execution.checkout_sha256 != sha256(proof.checkout_jwt.as_bytes())
        || closed_digest(&proof.closed_sd_jwt) != intent.target
        || r.digest() != worker.input_digest
        || r.execution.digest() != worker.output_digest
        || r.execution.digest() != intent.parameters_digest
        || r.execution.payee.trim().is_empty()
        || r.execution.network.trim().is_empty()
        || r.execution.currency.len() != 3
        || !r.execution.currency.bytes().all(|b| b.is_ascii_uppercase())
        || r.execution.instrument_digest == Digest32::ZERO
        || r.execution.amount_minor == 0
    {
        return Err("AP2 role result does not bind the exact execution and mandate");
    }
    if spec.now < 0
        || spec.max_role_age < 0
        || spec.max_checkpoint_age < 0
        || c.issued_at < 0
        || r.closed_issued_at < 0
        || r.validated_at < r.closed_issued_at
        || r.validated_at > spec.now
        || r.expires_at <= spec.now
        || spec
            .now
            .checked_sub(r.validated_at)
            .is_none_or(|n| n > spec.max_role_age)
        || c.issued_at >= spec.now
        || spec
            .now
            .checked_sub(c.issued_at)
            .is_none_or(|n| n > spec.max_checkpoint_age)
        || c.profile_digest != PROFILE_DIGEST_HEX
    {
        return Err("AP2 role/checkpoint freshness rejected");
    }
    signature(&spec.role_public_key, r.digest(), &proof.role_signature)?;
    let token = match (&r.flow, &proof.open_sd_jwt, r.open_sha256, r.open_issued_at) {
        (Ap2Flow::Direct, None, None, None) if c.issued_at >= r.closed_issued_at => {
            &proof.closed_sd_jwt
        }
        (Ap2Flow::Autonomous, Some(open), Some(hash), Some(issued))
            if issued >= 0
                && issued <= c.issued_at
                && c.issued_at < r.closed_issued_at
                && hash == sha256(open.as_bytes()) =>
        {
            open
        }
        _ => return Err("AP2 flow or open-before-closed binding rejected"),
    };
    signature(
        &spec.log_public_key,
        c.digest(),
        &proof.checkpoint_signature,
    )?;
    let steps: Vec<_> = proof
        .steps
        .iter()
        .map(|p| ProofStep {
            kind: p.kind.clone(),
            direction: p.direction.clone(),
            hash: p.hash,
        })
        .collect();
    if !verify_proof_at(
        token.as_bytes(),
        c.leaf_count as usize,
        proof.leaf_index as usize,
        &steps,
        &c.root,
    )
    .map_err(|_| "AP2 mandate inclusion rejected")?
    {
        return Err("AP2 mandate absent from retained checkpoint");
    }
    Ok(())
}
